/**
 * Flight plan — deterministic camera hints derived from the timeline.
 *
 * The chase camera used to estimate ground speed from successive wall-clock
 * samples (noisy, lagging, and wrong for a frame after every seek). The
 * timeline knows the exact route metres per timeline-ms, so the on-screen
 * speed is simply that × the clock rate. Leg statistics (length, bounding box,
 * real-world speed) are precomputed too, so the per-frame zoom policy is O(1)
 * instead of a re-walk of the leg path.
 */

import type { PlaybackPosition } from "./types";

const MI_PER_M = 0.000621371;

/** Metres of road the car covers per wall second at the given timeline rate (timeline-ms per wall-ms). */
export function groundSpeedMps(pos: PlaybackPosition | null | undefined, rate: number): number {
  if (!pos || pos.phase !== "travel") return 0;
  return pos.metersPerMs * Math.max(0, rate) * 1000;
}

/** Real-world average speed of the current leg in mph (999 when unknown — legacy sentinel). */
export function legSpeedMph(pos: PlaybackPosition): number {
  const g = pos.segment.geometry;
  if (!g || g.realSpeedMps == null) return 999;
  return g.realSpeedMps * 3600 * MI_PER_M;
}

/** Cab / live-nav follow — close enough to read the road, not continent overview. */
export function travelZoomForLegKm(km: number): number {
  if (km < 30) return 16.4;
  if (km < 80) return 15.8;
  if (km < 160) return 15.2;
  if (km < 320) return 14.6;
  return 14.0;
}

export interface TravelZoomOptions {
  /** Google basemap (hybrid 2D or Map3D): nudge closer. */
  google?: boolean;
  /** Google 2D CSS-tilt chase: tilt eats visual scale, nudge further. */
  cssChase?: boolean;
}

/**
 * Mapbox / Google-2D zoom for a travel position. Short confined legs (city
 * loops, trail spurs) get street-nav close; highways follow `travelZoomForLegKm`.
 */
export function travelZoom(pos: PlaybackPosition, opts: TravelZoomOptions = {}): number {
  const g = pos.segment.geometry;
  const km = g ? g.meters / 1000 : 0;
  const bbox = g ? g.bboxMeters / 1000 : 0;
  const mph = legSpeedMph(pos);
  const circling = bbox > 0 && bbox < Math.max(1.2, km * 0.45);
  const confined = bbox < 7.5 && (circling || km < 14);
  const slow = mph < 28;
  let zoom: number;
  if ((confined && slow) || (bbox < 3.2 && km < 9)) {
    const span = Math.max(0.28, bbox || km);
    zoom = Math.min(16.2, Math.max(14.2, 15.6 - Math.log2(span)));
  } else {
    zoom = travelZoomForLegKm(km);
  }
  if (opts.google) zoom = Math.min(17.6, zoom + (opts.cssChase ? 1.35 : 0.95));
  return zoom;
}

/** Look-ahead distance (m) that keeps the car in the lower third at a given zoom. */
export function lookAheadMeters(zoom: number): number {
  if (zoom >= 15) return 35;
  if (zoom >= 14) return 50;
  if (zoom >= 13) return 75;
  if (zoom >= 12) return 120;
  return 200;
}
