/**
 * Small numeric helpers shared by the playback engine. Geodesy lives in
 * `map/camera-math` — this file only adds what the timeline needs on top:
 * binary search over monotonic arrays, angle interpolation and the
 * geojson-vt web-mercator projection Mapbox uses for `line-progress`.
 */

export { haversineMeters, bearingBetween, normalizeHeading, clamp } from "../map/camera-math";

/**
 * Largest index `i` with `arr[i] <= value` (0 when `value` is below the first
 * entry, `arr.length - 1` when it is past the last). `arr` must be
 * non-decreasing. O(log n).
 */
export function lowerBound(arr: ArrayLike<number>, value: number): number {
  let lo = 0;
  let hi = arr.length - 1;
  if (hi < 0) return 0;
  if (value <= arr[0]) return 0;
  if (value >= arr[hi]) return hi;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (arr[mid] <= value) lo = mid;
    else hi = mid;
  }
  return lo;
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

/** Shortest-arc interpolation between two headings in degrees. */
export function lerpAngle(a: number, b: number, t: number): number {
  const diff = ((b - a + 540) % 360) - 180;
  return (((a + diff * t) % 360) + 360) % 360;
}

/**
 * geojson-vt projection (x, y in [0, 1]). Mapbox measures `line-progress`
 * along this projected line, so the trail tip fraction must be computed in
 * the same space or it drifts away from the car on long north–south routes.
 */
export function mercatorX(lng: number): number {
  return lng / 360 + 0.5;
}

export function mercatorY(lat: number): number {
  const sin = Math.sin((lat * Math.PI) / 180);
  const y = 0.5 - (0.25 * Math.log((1 + sin) / (1 - sin))) / Math.PI;
  return y < 0 ? 0 : y > 1 ? 1 : y;
}

export function mercatorDistance(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const dx = mercatorX(lng2) - mercatorX(lng1);
  const dy = mercatorY(lat2) - mercatorY(lat1);
  return Math.sqrt(dx * dx + dy * dy);
}
