/// <reference types="vite/client" />

import "./styles/diary.css";
import "./styles/cinema.css";
import "./styles/atlas.css";
import "./styles/ledger.css";
import "mapbox-gl/dist/mapbox-gl.css";
import type { SiteData, Trip } from "./types";
import { hydrateShell } from "./shell";
import { applyMediaCdn, resolveMediaCdnBase } from "./media-cdn";
import { configureTripGeometry } from "./data/trip-geometry";
import { colorForTripId } from "./ui/trip-colors";
import { runDiaryApp } from "./legacy/diary-app.js";

declare global {
  interface Window {
    __MMD_TRIPS: SiteData["trips"];
    __MMD_DASHBOARD: SiteData["dashboard"];
    __MMD_MAPBOX_B64: string;
    __MMD_GOOGLE_MAPS_B64: string;
    __MMD_PHOTO_FULL: boolean;
    __MMD_JOURNEY_TRIP_IDS?: Set<string>;
    __MMD_IS_JOURNEY_TRIP?: (trip: SiteData["trips"][number]) => boolean;
    /** Shelf order (newest journey first) — drives "Next journey" and auto-next. */
    __MMD_SHELF_ORDER?: string[];
    /** On-foot / ferry copy. `mostId` is the road that walked the farthest. */
    __MMD_ON_FOOT?: {
      labelFor: (trip: Trip) => string;
      mostId: string;
    };
    /** Longest driving sitting. `mostId` is the road with the longest one. */
    __MMD_HAUL?: {
      labelFor: (trip: Trip) => string;
      mostId: string;
    };
    /** Boot + lazy-geometry timings for scripts/verify_boot_perf.py. */
    __MMD_PERF: {
      indexMs: number;
      indexBytes: number;
      tripLoads: Array<{ id: string; ms: number; bytes: number }>;
    };
  }
}

const DATA_BASE = "./data/";

async function loadSiteIndex(): Promise<SiteData> {
  const res = await fetch(`${DATA_BASE}index.json`);
  if (!res.ok) {
    throw new Error(`Failed to load journey index (${res.status})`);
  }
  return res.json() as Promise<SiteData>;
}

/**
 * The atlas draws every trip from its overview polyline; the full mapped road
 * arrives with the per-trip chunk when a journey is focused or played.
 */
function seedOverviewGeometry(trips: Trip[]): void {
  for (const trip of trips) {
    if (!Array.isArray(trip.route_path)) {
      trip.route_path = trip.route_overview || [];
    }
    if (!trip.geometry) trip.geometry_loaded = true;
  }
}

async function boot() {
  const t0 = performance.now();
  const raw = await loadSiteIndex();
  window.__MMD_PERF = {
    indexMs: performance.now() - t0,
    indexBytes: JSON.stringify(raw).length,
    tripLoads: [],
  };
  const data = applyMediaCdn(raw);
  // Stable cinematic color per trip id before shelf / map boot (same palette everywhere).
  for (const trip of data.trips || []) {
    if (trip?.id) trip.color = colorForTripId(trip.id);
  }
  seedOverviewGeometry(data.trips);
  configureTripGeometry({
    dataBase: DATA_BASE,
    mediaCdnBase: resolveMediaCdnBase(data),
    onLoaded: ({ trip, ms, bytes }) => {
      window.__MMD_PERF.tripLoads.push({ id: trip.id, ms: Math.round(ms), bytes });
    },
  });
  window.__MMD_TRIPS = data.trips;
  window.__MMD_DASHBOARD = data.dashboard;
  window.__MMD_MAPBOX_B64 = data.mapbox_token_b64 || "";
  window.__MMD_GOOGLE_MAPS_B64 = data.google_maps_api_key_b64 || "";
  window.__MMD_PHOTO_FULL = data.photo_full_enabled ?? false;

  hydrateShell(data);
  runDiaryApp();
}

export function showBootError(message: string): void {
  const splash = document.getElementById("splash");
  if (splash) splash.classList.add("hidden");
  const panel = document.getElementById("boot-error");
  if (!panel) return;
  panel.hidden = false;
  const detail = document.getElementById("boot-error-detail");
  if (detail) detail.textContent = message;
  document.getElementById("boot-error-retry")?.addEventListener("click", () => location.reload());
}

boot().catch((err) => {
  console.error(err);
  showBootError(`Could not load journey data: ${err?.message || err}`);
});
