/**
 * On foot / by ferry — answers “how much of this road left the car?”
 *
 * The index ships `walk_miles` and `ferry_miles` (summed at export from
 * playback travel legs). Until that export exists, a loaded trip chunk’s
 * `playback.segments` answer the same question. Nothing here fetches geometry
 * or moves the camera.
 */
import type { Trip } from "../types";
import { tripTitle } from "./journeys";

/** Below this, a spur is noise (a driveway, a pin snap), not a walk. */
export const MIN_ON_FOOT_MILES = 0.5;

export interface ModeMiles {
  walk: number;
  ferry: number;
}

export interface OnFootPick {
  id: string;
  walk: number;
  /** "Most on foot · 6.4 mi · Bellevue → Redondo Beach" */
  sheetLabel: string;
}

interface TravelSegment {
  type?: string;
  profile?: string;
  leg_miles?: number;
}

export function formatModeMiles(miles: number): string {
  if (!Number.isFinite(miles) || miles <= 0) return "0";
  if (miles >= 10) return Math.round(miles).toLocaleString();
  const rounded = Math.round(miles * 10) / 10;
  return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
}

export function modeMilesFromSegments(segments: unknown): ModeMiles {
  let walk = 0;
  let ferry = 0;
  if (!Array.isArray(segments)) return { walk: 0, ferry: 0 };
  for (const raw of segments) {
    if (!raw || typeof raw !== "object") continue;
    const seg = raw as TravelSegment;
    if (seg.type !== "travel") continue;
    const miles = Number(seg.leg_miles) || 0;
    if (miles <= 0) continue;
    const profile = String(seg.profile || "driving");
    if (profile === "walking") walk += miles;
    else if (profile === "ferry") ferry += miles;
  }
  return { walk, ferry };
}

/** Prefer the export numbers so the label cannot drift when a chunk loads. */
export function modeMiles(trip: Pick<Trip, "walk_miles" | "ferry_miles" | "playback"> | null | undefined): ModeMiles {
  if (!trip) return { walk: 0, ferry: 0 };
  if (trip.walk_miles != null || trip.ferry_miles != null) {
    return {
      walk: Number(trip.walk_miles) || 0,
      ferry: Number(trip.ferry_miles) || 0,
    };
  }
  const playback = trip.playback as { segments?: unknown } | undefined;
  return modeMilesFromSegments(playback?.segments);
}

/** "6.4 mi on foot · 2.4 mi by ferry" — empty when both are under the floor. */
export function onFootSentence(walk: number, ferry: number): string {
  const parts: string[] = [];
  if (walk >= MIN_ON_FOOT_MILES) parts.push(`${formatModeMiles(walk)} mi on foot`);
  if (ferry >= MIN_ON_FOOT_MILES) parts.push(`${formatModeMiles(ferry)} mi by ferry`);
  return parts.join(" · ");
}

export function onFootLabel(trip: Pick<Trip, "walk_miles" | "ferry_miles" | "playback"> | null | undefined): string {
  const { walk, ferry } = modeMiles(trip);
  return onFootSentence(walk, ferry);
}

/** Town-level title. Drops the round-trip suffix so the sheet stays a place. */
export function roadPlace(trip: Pick<Trip, "name" | "origin_label" | "story_dest" | "dest_label">): string {
  const title = tripTitle(trip)
    .replace(/\s*\(Round Trip\)\s*$/i, "")
    .replace(/\s*·\s*Sunrise\s*$/i, "")
    .trim();
  return title || "this road";
}

function beats(candidate: Trip, walk: number, best: Trip, bestWalk: number): boolean {
  if (walk > bestWalk + 1e-9) return true;
  if (Math.abs(walk - bestWalk) > 1e-9) return false;
  const miles = Number(candidate.miles) || 0;
  const bestMiles = Number(best.miles) || 0;
  if (miles !== bestMiles) return miles > bestMiles;
  return String(candidate.start || "") > String(best.start || "");
}

/**
 * The road with the most miles on foot. Ties: more total miles, then the
 * later start. Short drives count. Ferry miles do not win this line.
 */
export function mostOnFoot(trips: readonly Trip[]): OnFootPick | null {
  let best: Trip | null = null;
  let bestWalk = 0;
  for (const trip of trips) {
    const { walk } = modeMiles(trip);
    if (walk < MIN_ON_FOOT_MILES) continue;
    if (!best || beats(trip, walk, best, bestWalk)) {
      best = trip;
      bestWalk = walk;
    }
  }
  if (!best) return null;
  return {
    id: best.id,
    walk: bestWalk,
    sheetLabel: `Most on foot · ${formatModeMiles(bestWalk)} mi · ${roadPlace(best)}`,
  };
}
